mapper.select:
SELECT user_id, auth_provider, social_id, login_id, email,
       nickname, profile_image_url, github_username,
       role, created_at, updated_at
FROM users
WHERE auth_provider = #{authProvider}
  AND social_id = #{socialId}

SELECT EXISTS (
    SELECT 1 FROM users WHERE user_id = #{userId}
)

SELECT EXISTS (
    SELECT 1 FROM users WHERE email = #{email}
)

mapper.update:
UPDATE users
SET password = #{password}, updated_at = NOW()
WHERE user_id = #{userId}
